package com.bank.convert;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ConversionDemo {
    private static final Logger log = Logger.getLogger(ConversionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        ConversionDemoService svc = new ConversionDemoService();

        // 1) Implicit widening: int -> long -> double (safe, no cast).
        double widened = svc.safeWiden(50000);
        log.info(() -> "Widened int 50000 to double = " + widened);

        // 2) Money through float LOSES precision — never do this with money.
        long paise = 123_456_789_012L;    // large paise figure
        float lossy = svc.moneyToFloatLossy(paise);
        log.warning(() -> "paise=" + paise + " as float=" + (long) lossy
                + " (precision LOST — use BigDecimal)");

        // 3) Narrowing double -> int TRUNCATES, does not round.
        int truncated = svc.truncateRate(7.95);
        log.warning(() -> "truncateRate(7.95) = " + truncated + " (fraction dropped, not rounded)");

        // 4) char conversions: widening is implicit, narrowing needs a cast.
        int letterCode = 'R';              // widening char->int is implicit
        log.info(() -> "'R' widened to int = " + letterCode);
        char fromInt = svc.charFromCode(66);     // int->char needs cast
        log.info(() -> "charFromCode(66) = " + fromInt);

        // Signed byte -> char surprise.
        byte neg = -1;
        char surprising = (char) neg;      // -1 becomes 65535
        log.warning(() -> "(char)(byte)-1 = " + (int) surprising + " (signed byte -> huge char)");

        log.info(() -> "Balance stays BigDecimal: " + rajesh.getBalance());
    }
}

