class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in service/ConversionDemoService.java in a real project ───
class ConversionDemoService {
    private static final Logger log = Logger.getLogger(ConversionDemoService.class.getName());

    // Implicit widening: int widens to long then to double with no cast.
    double safeWiden(int rupees) {
        long asLong = rupees;    // int -> long (implicit)
        return asLong;           // long -> double (implicit)
    }

    // Demonstrates precision loss: money must NEVER go through float.
    float moneyToFloatLossy(long paise) {
        return paise;            // long -> float (implicit widening, may round)
    }

    // Narrowing double -> int truncates the fractional part.
    int truncateRate(double rate) {
        return (int) rate;       // explicit cast; 7.95 becomes 7
    }

    // int -> char requires an explicit cast (unsigned 16-bit range).
    char charFromCode(int code) {
        return (char) code;
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
